//! The ribbon's Spec tab, for working on the spec: Build Spec, which runs
//! `piton build` in the project and says how it went, and the divergence
//! commands, which analyze the project or show its saved reports.

use gpui_kit::assets::IconName;
use gpui_kit::component::button::Button;
use gpui_kit::component::notification::Notification;
use gpui_kit::component::{Disableable as _, WindowExt as _};
use gpui_kit::*;

use super::{Command, CommandPlace, CommandSize, Ribbon};
use crate::divergence_view::{AnalyzeDivergence, ViewDivergenceReports};
use crate::generate_skills_view::GenerateSkills;
use crate::piton_build;
use crate::project_directory::ProjectDirectory;
use crate::rescope_view::Rescope;

pub(super) const COMMANDS: &[CommandPlace] = &[
    CommandPlace {
        command: Command::BuildSpec,
        group: "Build",
        size: CommandSize::Full,
        primary: true,
    },
    CommandPlace {
        command: Command::AnalyzeDivergence,
        group: "Analysis",
        size: CommandSize::Full,
        primary: true,
    },
    CommandPlace {
        command: Command::ViewDivergenceReports,
        group: "Analysis",
        size: CommandSize::Slim,
        primary: false,
    },
    CommandPlace {
        command: Command::GenerateSkills,
        group: "Skills",
        size: CommandSize::Full,
        primary: false,
    },
    CommandPlace {
        command: Command::Rescope,
        group: "Refactor",
        size: CommandSize::Full,
        primary: false,
    },
];

/// Analyze Divergence: opens the divergence panel and starts analyzing how the
/// code and the spec have diverged.
pub(super) fn analyze_divergence(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let project = ProjectDirectory::get(cx);
    button(
        "analyze-divergence",
        IconName::GitCompareArrows,
        "Analyze Divergence".into(),
    )
    .tooltip(if project.is_none() {
        "Open a project to analyze it"
    } else {
        "Analyze how the code and the spec have diverged"
    })
    .disabled(project.is_none())
    .on_click(|_, window, cx| window.dispatch_action(Box::new(AnalyzeDivergence), cx))
    .into_any_element()
}

/// View Divergence Reports: opens the divergence panel on the latest saved
/// report, starting nothing.
pub(super) fn view_divergence_reports(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let project = ProjectDirectory::get(cx);
    button(
        "view-divergence-reports",
        IconName::FileText,
        "View Divergence Reports".into(),
    )
    .tooltip(if project.is_none() {
        "Open a project to view its reports"
    } else {
        "Show the reports of earlier divergence analyses"
    })
    .disabled(project.is_none())
    .on_click(|_, window, cx| window.dispatch_action(Box::new(ViewDivergenceReports), cx))
    .into_any_element()
}

/// Generate Skills: opens the Generate Skills panel, which ranks the spec's
/// scopes for the skills worth building.
pub(super) fn generate_skills(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let project = ProjectDirectory::get(cx);
    button(
        "generate-skills",
        IconName::Sparkles,
        "Generate Skills".into(),
    )
    .tooltip(if project.is_none() {
        "Open a project to generate skills for it"
    } else {
        "Find which scopes skills should be built for"
    })
    .disabled(project.is_none())
    .on_click(|_, window, cx| window.dispatch_action(Box::new(GenerateSkills), cx))
    .into_any_element()
}

/// Rescope: opens the Rescope panel, which looks for concepts the spec repeats
/// that could be scopes of their own, or brings back a minimized one.
pub(super) fn rescope(
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let project = ProjectDirectory::get(cx);
    button("rescope", IconName::Shapes, "Rescope".into())
        .tooltip(if project.is_none() {
            "Open a project to rescope its spec"
        } else {
            "Find concepts the spec repeats that could be scopes of their own"
        })
        .disabled(project.is_none())
        .on_click(|_, window, cx| window.dispatch_action(Box::new(Rescope), cx))
        .into_any_element()
}

/// Build Spec: disabled rather than hidden until it can run, so it is always
/// found in the same place, with the tooltip saying why.
pub(super) fn build_spec(
    ribbon: &Ribbon,
    button: impl Fn(&'static str, IconName, SharedString) -> Button,
    cx: &mut Context<Ribbon>,
) -> AnyElement {
    let project = ProjectDirectory::get(cx);
    let tooltip = if project.is_none() {
        "Open a project to build its spec"
    } else if ribbon.building {
        "The spec is building"
    } else {
        "Run piton build to compile the spec"
    };
    button("build", IconName::Hammer, "Build Spec".into())
        .tooltip(tooltip)
        .loading(ribbon.building)
        .disabled(project.is_none() || ribbon.building)
        .on_click(cx.listener(|this, _, window, cx| this.build(window, cx)))
        .into_any_element()
}

impl Ribbon {
    /// Whether a build is running.
    pub fn is_building(&self) -> bool {
        self.building
    }

    /// Whether Build can run: there is a project and no build is running.
    pub fn can_build(&self, cx: &App) -> bool {
        ProjectDirectory::get(cx).is_some() && !self.building
    }

    /// Runs `piton build` in the project, then says how it went.
    pub fn build(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(dir) = ProjectDirectory::get(cx).filter(|_| !self.building) else {
            return;
        };
        self.building = true;
        cx.notify();

        let build = piton_build::run(dir, cx);
        cx.spawn_in(window, async move |this, cx| {
            let result = build.await;
            this.update_in(cx, |this, window, cx| {
                this.building = false;
                cx.notify();
                let note = match result {
                    Ok(outcome) if outcome.success => {
                        let title = match outcome.files.len() {
                            1 => "Built 1 file".to_string(),
                            count => format!("Built {count} files"),
                        };
                        let files = outcome.files;
                        Notification::success("")
                            .title(title)
                            .content(move |_, _, _| {
                                // One line per written file, never wrapped.
                                gpui_kit::component::v_flex()
                                    .children(files.iter().map(|file| {
                                        gpui_kit::component::label::Label::new(file.clone())
                                            .whitespace_nowrap()
                                            .truncate()
                                    }))
                                    .into_any_element()
                            })
                    }
                    Ok(outcome) => Notification::error(outcome.report).title("Build failed"),
                    Err(err) => {
                        Notification::error(err.to_string()).title("Could not run piton build")
                    }
                };
                window.push_notification(note, cx);
            })
            .ok();
        })
        .detach();
    }
}
//! A floating panel over the whole main window, inset from its edges, with the
//! window dimmed behind it. It is modal: clicking the dimmed window closes it,
//! nothing beneath takes the mouse, and <Tab> cycles focus within it. Keeping
//! focus from going beneath otherwise is up to whatever shows it.
//!
//! It comes in and goes away with the rise-in animation (see
//! [`crate::animations::rise_in`]): the panel is its surface, and the dimmed
//! window its dimming.

use gpui_kit::component::{ActiveTheme as _, FocusTrapElement as _};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::animations::rise_in::{self, Direction};

/// How far the panel is inset from each edge of the window.
pub const INSET: Pixels = px(32.);

/// The panel's surface, holding `content`, filling its place.
fn surface(content: impl IntoElement, cx: &App) -> Div {
    let theme = cx.theme();
    div()
        .absolute()
        .inset_0()
        .overflow_hidden()
        .rounded_lg()
        .border_1()
        .border_color(theme.border)
        .bg(theme.background)
        .shadow_2xl()
        .child(content)
}

/// `content` in a panel whose elements are named `{name}-panel` and
/// `{name}-backdrop`, tracking `focus` and trapping <Tab> within it, and
/// calling `close` when the dimmed window around it is clicked. `opened`
/// counts the times a panel has opened, so each comes in afresh.
pub fn inset_panel(
    name: &str,
    focus: &FocusHandle,
    content: impl IntoElement,
    close: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    opened: usize,
    cx: &App,
) -> AnyElement {
    // Focus is tracked and trapped within what the panel holds.
    let content = div()
        .size_full()
        .track_focus(focus)
        .child(content)
        .focus_trap(SharedString::from(format!("{name}-trap")), focus);
    let moving = surface(content, cx)
        .id(SharedString::from(format!("{name}-panel-surface")))
        // Lets UI tests find the surface as it moves; inert in normal builds.
        .map(gpui_kit::TestSupportExt::test_support);
    // Where the panel settles, which it moves within as it comes in.
    let panel = div()
        .id(SharedString::from(format!("{name}-panel")))
        .absolute()
        .inset(INSET)
        // Clicks inside stay inside, rather than reaching the backdrop.
        .occlude()
        .child(rise_in::surface(
            moving,
            "inset-panel",
            opened,
            Direction::In,
        ));
    // Lets UI tests find the panel; inert in normal builds.
    let panel = gpui_kit::TestSupportExt::test_support(panel);
    let backdrop = div()
        .id(SharedString::from(format!("{name}-backdrop")))
        .absolute()
        .inset_0()
        // Nothing beneath takes the mouse while the panel is open.
        .occlude()
        .on_click(close)
        .child(rise_in::dimming("inset-panel", opened, Direction::In, cx))
        .child(panel);
    // Lets UI tests find the panel and backdrop; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(backdrop).into_any_element()
}

/// A panel closing: `content` going away, taking neither the mouse nor focus.
/// `closed` counts the times a panel has closed, so each goes away afresh.
pub fn closing_panel(content: AnyView, closed: usize, cx: &App) -> AnyElement {
    let panel = rise_in::surface(
        surface(div().size_full().child(content), cx),
        "inset-panel",
        closed,
        Direction::Out,
    );
    div()
        .absolute()
        .inset_0()
        .child(rise_in::dimming("inset-panel", closed, Direction::Out, cx))
        .child(div().absolute().inset(INSET).child(panel))
        .into_any_element()
}
//! A text input that grows to fit its text: a row for each visual line, lines
//! broken with Enter and long lines that soft wrap alike, from a single row up
//! to a most, after which it scrolls. It shrinks as text goes, and fits again
//! when its width changes. Whatever shows the input keeps a [`GrowToFit`],
//! sizes the editor with [`GrowToFit::heights`], and puts
//! [`GrowToFit::tracker`] over it, so the fit follows how the editor is laid
//! out.

use gpui_kit::component::ActiveTheme as _;
use gpui_kit::component::input::EditorState;
use gpui_kit::*;

/// Room the editor keeps free at the right of each line when soft wrapping.
const WRAP_RIGHT_MARGIN: Pixels = px(10.);

/// How an input is fitted to its text, from how its editor was last laid out.
pub struct GrowToFit {
    max_rows: usize,
    /// Width the editor's text was last laid out in, which decides where long
    /// lines soft wrap.
    text_width: Option<Pixels>,
    /// What the editor adds around its rows (padding and border) as last
    /// laid out, rounded to device pixels.
    chrome: Option<Pixels>,
}

impl GrowToFit {
    /// Grows up to `max_rows` rows.
    pub fn new(max_rows: usize) -> Self {
        Self {
            max_rows,
            text_width: None,
            chrome: None,
        }
    }

    /// How tall the editor is for its text, and how tall a single row of it
    /// is, for lining things up with it.
    pub fn heights(
        &self,
        editor: &Entity<EditorState>,
        window: &Window,
        cx: &App,
    ) -> (Pixels, Pixels) {
        let text = editor.read(cx).value();
        let rows = self.visual_rows(&text, window, cx).clamp(1, self.max_rows);
        // Fit the text with the editor's own metrics: its laid-out line height
        // plus the padding and border around its rows. Until the editor has
        // painted, the border is estimated at a device pixel or more per side.
        let line_height = editor
            .read(cx)
            .line_height()
            .unwrap_or_else(|| window.line_height());
        let chrome = self.chrome.unwrap_or_else(|| {
            gpui_kit::component::Size::Medium.input_py() * 2.
                + ceil_to_device_pixel(px(1.), window) * 2.
        });
        (
            ceil_to_device_pixel(line_height * rows as f32 + chrome, window),
            ceil_to_device_pixel(line_height + chrome, window),
        )
    }

    /// The rows `text` takes in the editor: one per line, plus one for every
    /// soft wrap, wrapped the way the editor wraps it.
    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
            return text.split('\n').count();
        };
        let theme = cx.theme();
        let mut wrapper = window
            .text_system()
            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
        text.split('\n')
            .map(|line| {
                1 + wrapper
                    .wrap_line(&[LineFragment::text(line)], wrap_width)
                    .count()
            })
            .sum()
    }

    /// Laid over the editor: once the editor has painted, checks how it was
    /// laid out, the width its text wrapped in and the padding and border
    /// around its rows, and when either changed, has `owner`, which keeps the
    /// fit where `fit` finds it, draw again to fit anew.
    pub fn tracker<T: 'static>(
        editor: &Entity<EditorState>,
        owner: WeakEntity<T>,
        fit: fn(&mut T) -> &mut GrowToFit,
    ) -> impl IntoElement {
        let editor = editor.clone();
        canvas(
            |_, _, _| {},
            move |bounds, _, _, cx| {
                let Some(text_bounds) = editor.read(cx).text_bounds() else {
                    return;
                };
                let width = text_bounds.size.width;
                let chrome = bounds.size.height - text_bounds.size.height;
                owner
                    .update(cx, |owner, cx| {
                        let fit = fit(owner);
                        let chrome_changed =
                            fit.chrome.is_none_or(|old| (old - chrome).abs() > px(0.01));
                        if fit.text_width != Some(width) || chrome_changed {
                            fit.text_width = Some(width);
                            if chrome_changed {
                                fit.chrome = Some(chrome);
                            }
                            cx.notify();
                        }
                    })
                    .ok();
            },
        )
        .absolute()
        .size_full()
    }
}

/// `length` rounded up to a whole device pixel. The editor lays its rows out
/// on device pixels, and rounds a height that falls between device pixels
/// half toward zero, so at fractional scales an input sized in logical pixels
/// can come out a fraction of a pixel short of its rows; the editor then takes
/// its last row for out of view and scrolls it in for a frame, which flickers
/// the text a line up and back.
pub fn ceil_to_device_pixel(length: Pixels, window: &Window) -> Pixels {
    let scale_factor = window.scale_factor();
    // Float noise just past a whole device pixel must not round up to the next.
    px((f32::from(length) * scale_factor - 1e-3).ceil() / scale_factor)
}
