    if let Some(view) = self.divergence.clone() {
        view.update(cx, |view, cx| view.open_to(opening, cx));
        self.restore_divergence(&view, window, cx);
        return;
    }
    let Some(project_dir) = ProjectDirectory::get(cx) else {
