/// A command in the ribbon, from whichever tab holds it.
#[derive(Clone, Copy, Debug, PartialEq)]
enum Command {
    NewProject,
    OpenProject,
    BuildSpec,
    AnalyzeDivergence,
    ViewDivergenceReports,
    GenerateSkills,
    Rescope,
    DarkMode,
    Settings,
}

/// Where a command sits in its tab, and whether it stays in the collapsed
/// ribbon.
struct CommandPlace {
    command: Command,
    group: &'static str,
    /// Full or slim.
    size: CommandSize,
    /// Shown, small, in the collapsed ribbon.
    primary: bool,
}

/// How a command's button is laid out.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CommandSize {
    /// The full height of the body, its icon large above its label.
    Full,
